def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    credible_bids = []
    stressed_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                stressed_count += 1
            prev = opp.get('previous_trace') or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= bid * 0.8:
                    credible_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    capacity = int(supply / WATER_REQ)
    my_urgent = (hp <= 3) or (no_water_days >= 1)
    scarce = capacity <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_credible = max(credible_bids) if credible_bids else highest_prev

    target = 0.0

    if my_urgent:
        target = max(62.0, highest_credible + 2.0)
        if scarce:
            target = max(target, 78.0)
    elif scarce:
        if highest_credible >= 100.0:
            target = 36.0
        else:
            target = max(52.0, highest_credible + 1.5)
    else:
        if stressed_count >= 2:
            target = 20.0
        elif highest_credible >= 100.0:
            target = 28.0
        elif highest_credible >= 70.0:
            target = 44.0
        elif highest_credible > 0.0:
            target = max(34.0, highest_credible * 0.72)
        else:
            target = 38.0

    if day >= 8 and hp >= 5 and not my_urgent:
        target *= 0.9

    reserve = 0.0
    if hp >= 4 and day <= 7:
        reserve = 20.0
    bid = min(float(budget) - reserve, target)

    if my_urgent and budget > 0:
        bid = max(bid, min(float(budget), 60.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = float(budget)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append((oid, o))

    if not alive_opps:
        # If no opponents, take a safe moderate bid
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Use only yesterday_trace for immediate reaction
    prev_bids = []
    prev_bids_by_opp = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
                prev_bids.append(b)
                prev_bids_by_opp[oid] = b
            except Exception:
                pass

    # Estimate pressure from surviving opponents' yesterday bids
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        median_prev_bid = sorted(prev_bids)[len(prev_bids)//2]
    else:
        highest_prev_bid = 0.0
        median_prev_bid = 0.0

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # If I'm low HP, prioritize survival: bid enough to secure water share.
    low_hp = my_hp <= 2.0

    # Supply-based aggressiveness: higher supply reduces need to outbid.
    # Normalize supply into [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Base target: track Alex-like behavior (high bids) but avoid overpaying.
    # When supply is low (near 15), increase bid; when high (near 25), decrease.
    scarcity_multiplier = 0.75 + (1.0 - supply_norm) * 0.6  # ~0.75..1.35

    # Determine target bid using yesterday pressure.
    # If someone already bid very high yesterday, we slightly undercut to win.
    # Otherwise bid around median to beat low bidders.
    pressure = 0.0
    if highest_prev_bid > 0.0:
        pressure = highest_prev_bid

    # Compute candidate bids
    if pressure >= DAILY_SALARY * 0.95:
        # Very aggressive opponent yesterday; try to be competitive but not max.
        target = pressure * 0.92
    elif pressure >= DAILY_SALARY * 0.7:
        target = max(median_prev_bid * 0.95, DAILY_SALARY * 0.55)
    else:
        target = max(median_prev_bid * 0.9, DAILY_SALARY * 0.5)

    # Adjust by my HP and scarcity
    if low_hp:
        target *= 1.35
    else:
        # If reasonably healthy, be slightly more opportunistic
        if my_hp >= 6.0:
            target *= 1.15
        else:
            target *= 1.0

    target *= scarcity_multiplier

    # Late game: slightly increase bid to avoid end-of-episode collapse
    if day >= 7:
        target *= 1.08

    # Hard caps to avoid bankruptcy
    # Keep some budget reserve proportional to remaining days
    remaining_days = max(1, 10 - day)
    reserve = my_budget * 0.15
    max_safe = my_budget - reserve
    if max_safe < 0.0:
        max_safe = my_budget * 0.5

    # Ensure at least enough to matter, but never exceed safe cap
    min_bid = DAILY_SALARY * (0.35 if not low_hp else 0.65)
    bid = float(target)

    if bid < min_bid:
        bid = min_bid

    if bid > max_safe:
        bid = max_safe

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    if my_budget < 0.0:
        return 0.0
    if bid > my_budget:
        bid = my_budget

    return bid

