def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid conservatively to secure water without overspending.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_value = 0.0

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # High competition detected from yesterday's bids (e.g., opponents bidding very high)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3 and my_status['no_water_days'] == 0:
                # If doing well and others are bidding high, try to save budget by bidding lower
                bid_value = DAILY_SALARY * 0.3
            else:
                # If not doing well (low HP or missed water), prioritize survival with an aggressive bid
                bid_value = DAILY_SALARY * 0.95
        else:
            # Moderate competition, try to slightly outbid the highest previous bid
            bid_value = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

            # Additional aggressiveness if I'm in a bad state or it's late in the game
            if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
                bid_value = max(bid_value, DAILY_SALARY * 0.95)
            elif day_context['day'] >= EPISODE_DAYS - 2: # Last two days of the episode
                bid_value = max(bid_value, DAILY_SALARY * 0.8)
    else:
        # No yesterday's bids available (e.g., Day 1 of the meta-round or no valid bids from opponents)
        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            # Aggressive bid for survival if HP is critical or water was missed
            bid_value = DAILY_SALARY * 0.9
        elif day_context['day'] >= EPISODE_DAYS - 2:
            # Aggressive bid for the end game
            bid_value = DAILY_SALARY * 0.7
        else:
            # Default moderate bid
            bid_value = DAILY_SALARY * 0.55

    # Ensure bid does not exceed current budget and is at least 1.0 (if budget allows)
    final_bid = min(my_status['budget'], bid_value)
    return max(1.0, final_bid) if my_status['budget'] > 0 else 0.0

